package com.coffeeshop.model;import java.math.BigDecimal;import java.time.LocalDateTime;public final class DiscountModels{private DiscountModels(){}public record Discount(long id,String code,String name,String type,BigDecimal value,LocalDateTime validFrom,LocalDateTime validUntil,boolean active,byte[]version){public Discount{version=version.clone();}@Override public byte[]version(){return version.clone();}public boolean currentlyValid(LocalDateTime now){return active&&(validFrom==null||!now.isBefore(validFrom))&&(validUntil==null||now.isBefore(validUntil));}}}
